function elementLocatePayload(element, clipOverflow) {
  if (!element || typeof element.getBoundingClientRect !== "function") return null;
  const rect = elementBoundingRect(element, element.getBoundingClientRect(), clipOverflow);
  if (!rect) return null;
  const width = rect && rect.width != null ? rect.width : Number(rect && rect.right) - Number(rect && rect.left);
  const height = rect && rect.height != null ? rect.height : Number(rect && rect.bottom) - Number(rect && rect.top);
  const clientRect = {
    x: round2(rect && rect.left),
    y: round2(rect && rect.top),
    w: Math.max(0, round2(width)),
    h: Math.max(0, round2(height))
  };
  if (clientRect.w <= 0 || clientRect.h <= 0) return null;
  const visible = visibleClientRect(rect);
  return {
    x: clientRect.x,
    y: clientRect.y,
    w: Math.max(1, clientRect.w),
    h: Math.max(1, clientRect.h),
    client_rect: clientRect,
    client_rect_space: "frame_viewport_css",
    client_rect_source: "dom_get_bounding_client_rect",
    visible_client_rect: visible,
    is_visible_in_viewport: !!visible,
    viewport_w: Number(globalThis.innerWidth) || 0,
    viewport_h: Number(globalThis.innerHeight) || 0,
    dpr: Number(globalThis.devicePixelRatio) || 1,
    frame_depth: 0
  };
}

