fn execute_web_validation_probe(
    web_probe: &mut dyn WebProbeClient,
    command: &Value,
    timeout_ms: u64,
) -> Result<Value, String> {
    let deadline = Instant::now() + Duration::from_millis(timeout_ms);
    loop {
        let remaining_ms = deadline
            .saturating_duration_since(Instant::now())
            .as_millis()
            .clamp(1, u128::from(u64::MAX)) as u64;
        let mut request = command.clone();
        if let Some(object) = request.as_object_mut() {
            object.insert("timeoutMs".to_string(), json!(remaining_ms));
        }
        match web_probe.execute_web_dom(request) {
            Err(error)
                if (error.contains("browser_host_warming")
                    || error.contains("browser_window_mapping_warming"))
                    && Instant::now() < deadline =>
            {
                thread::sleep(Duration::from_millis(25));
            }
            result => return result,
        }
    }
